/**
 * COG (0.9, ml-cnv.2): the header reader, the URL translation shared by the
 * renderer and `mlym emit`, the thin `cog://` handler core registers (host
 * wins, reader loaded on demand), and the reader's preflight — every
 * failure the plugin would report as a raw string, or not at all (a
 * GeoTIFF in longitude/latitude draws blank with no error), in plain words.
 *
 * Fixtures: docs/public/gallery-assets/cloud-native/*.tif, generated by
 * scripts/fixtures/cog.py.
 */
import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { readFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const plugin = vi.hoisted(() => ({ cogProtocol: vi.fn(async () => ({ data: { tilejson: "2.2.0" } })) }));
vi.mock("@geomatico/maplibre-cog-protocol", () => plugin);

import { isCloudOptimized, isTiff, readCogHeader, type CogHeader } from "../../src/formats/cog-header";
import { cogSourceSpec, cogUrl, colorRampColors, colorRampFragment, normalizeHex } from "../../src/formats/cog-spec";
import { classifyCogError, fileUrlOf, handle } from "../../src/formats/cog";
import { cogHintFor, install } from "../../src/formats/cog-protocol";
import { getDecoder } from "../../src/formats/decoders";
import { isFormatError } from "../../src/formats/errors";

const FIXTURES = join(
  dirname(fileURLToPath(import.meta.url)),
  "..", "..", "..", "..", "docs", "public", "gallery-assets", "cloud-native"
);
const fixture = (name: string) => new Uint8Array(readFileSync(join(FIXTURES, name)));
const head = (name: string) => fixture(name).slice(0, 65536);

describe("readCogHeader — the first bytes of a GeoTIFF", () => {
  it("a COG in Web Mercator: tiles, overviews, EPSG:3857", () => {
    const h = readCogHeader(head("imagery.cog.tif")) as CogHeader;
    expect(h).toEqual({
      width: 512,
      height: 512,
      tileWidth: 256,
      tileHeight: 256,
      hasOverviews: true,
      crs: "EPSG:3857",
      webMercator: true,
    });
    expect(isCloudOptimized(h)).toBe(true);
    for (const name of ["elevation.cog.tif", "ndvi.cog.tif"]) {
      const other = readCogHeader(head(name)) as CogHeader;
      expect(other.webMercator, name).toBe(true);
      expect(isCloudOptimized(other), name).toBe(true);
    }
  });

  it("a COG in longitude/latitude is EPSG:4326, not Web Mercator", () => {
    const h = readCogHeader(head("imagery-4326.cog.tif")) as CogHeader;
    expect(h.crs).toBe("EPSG:4326");
    expect(h.webMercator).toBe(false);
  });

  it("an ordinary GeoTIFF in strips without overviews isn't cloud-optimized", () => {
    const h = readCogHeader(head("imagery-plain.tif")) as CogHeader;
    expect(h.tileWidth).toBeUndefined();
    expect(h.hasOverviews).toBe(false);
    expect(h.webMercator).toBe(true);
    expect(isCloudOptimized(h)).toBe(false);
  });

  it("a web page is not a TIFF; a header cut short is 'truncated'", () => {
    expect(readCogHeader(fixture("not-really.tif"))).toBe("not-tiff");
    expect(isTiff(new TextEncoder().encode("<!doctype html>"))).toBe(false);
    expect(readCogHeader(head("imagery.cog.tif").slice(0, 40))).toBe("truncated");
  });

  it("reads big-endian and BigTIFF headers, and a projected CRS by its EPSG code", () => {
    // Big-endian classic TIFF: 300×200, strips, GeoKeys: projected, EPSG:32632.
    const be = tiff({ big: false, le: false, width: 300, height: 200, projected: 32632 });
    expect(readCogHeader(be)).toMatchObject({ width: 300, height: 200, crs: "EPSG:32632", webMercator: false });
    const bigtiff = tiff({ big: true, le: true, width: 4096, height: 4096, tile: 512, projected: 3857, next: true });
    const h = readCogHeader(bigtiff) as CogHeader;
    expect(h).toMatchObject({ width: 4096, tileWidth: 512, hasOverviews: true, crs: "EPSG:3857", webMercator: true });
    expect(isCloudOptimized(h)).toBe(true);
    // No GeoKeys at all: a plain TIFF image.
    const plain = readCogHeader(tiff({ big: false, le: true, width: 10, height: 10 })) as CogHeader;
    expect(plain.crs).toBeUndefined();
    expect(plain.webMercator).toBe(false);
  });

  it("isCloudOptimized: small images pass either way; a big tiled one needs overviews", () => {
    const base = { webMercator: true, hasOverviews: false } as const;
    expect(isCloudOptimized({ ...base, width: 200, height: 200 })).toBe(true);
    expect(isCloudOptimized({ ...base, width: 512, height: 512, tileWidth: 256, tileHeight: 256 })).toBe(true);
    expect(isCloudOptimized({ ...base, width: 2048, height: 512, tileWidth: 256, tileHeight: 256 })).toBe(false);
  });
});

/** A minimal (Big)TIFF header with one IFD, for byte orders the fixtures don't cover. */
function tiff(o: {
  big: boolean;
  le: boolean;
  width: number;
  height: number;
  tile?: number;
  projected?: number;
  next?: boolean;
}): Uint8Array {
  const buf = new ArrayBuffer(1024);
  const v = new DataView(buf);
  const bytes = new Uint8Array(buf);
  bytes.set(o.le ? [0x49, 0x49] : [0x4d, 0x4d]);
  v.setUint16(2, o.big ? 43 : 42, o.le);
  const geo = o.projected !== undefined ? [1, 1, 0, 2, 1024, 0, 1, 1, 3072, 0, 1, o.projected] : undefined;
  const entries: [number, number, number[]][] = [
    [256, 4, [o.width]],
    [257, 4, [o.height]],
  ];
  if (o.tile) entries.push([322, 3, [o.tile]], [323, 3, [o.tile]]);
  if (geo) entries.push([34735, 3, geo]);
  const ifd = o.big ? 16 : 8;
  if (o.big) {
    v.setUint16(4, 8, o.le);
    v.setUint32(8, ifd, o.le);
    v.setUint32(12, 0, o.le);
    v.setUint32(ifd, entries.length, o.le);
  } else {
    v.setUint32(4, ifd, o.le);
    v.setUint16(ifd, entries.length, o.le);
  }
  const first = ifd + (o.big ? 8 : 2);
  const size = o.big ? 20 : 12;
  let extra = 600;
  entries.forEach(([tag, type, values], i) => {
    const at = first + i * size;
    v.setUint16(at, tag, o.le);
    v.setUint16(at + 2, type, o.le);
    if (o.big) v.setUint32(at + 4, values.length, o.le);
    else v.setUint32(at + 4, values.length, o.le);
    const field = at + (o.big ? 12 : 8);
    const width = type === 3 ? 2 : 4;
    const inline = values.length * width <= (o.big ? 8 : 4);
    const target = inline ? field : extra;
    if (!inline) {
      if (o.big) v.setUint32(field, extra, o.le);
      else v.setUint32(field, extra, o.le);
      extra += values.length * width;
    }
    values.forEach((n, j) => (width === 2 ? v.setUint16(target + j * 2, n, o.le) : v.setUint32(target + j * 4, n, o.le)));
  });
  const nextAt = first + entries.length * size;
  if (o.next) v.setUint32(nextAt, 900, o.le);
  return bytes;
}

describe("cog-spec — a COG source as the plugin reads it", () => {
  it("cogUrl: scheme, absolute file, #dem for elevation, the author's own fragment kept", () => {
    const abs = (u: string) => new URL(u, "https://site.org/repo/").href;
    expect(cogUrl("data/x.tif", { absolute: abs })).toBe("cog://https://site.org/repo/data/x.tif");
    expect(cogUrl("cog://data/x.tif", { type: "raster-dem", absolute: abs })).toBe(
      "cog://https://site.org/repo/data/x.tif#dem"
    );
    expect(cogUrl("x.tif#dem", { type: "raster-dem" })).toBe("cog://x.tif#dem");
    expect(cogUrl("x.tif?v=2#color:CartoEarth,1,100", { type: "raster" })).toBe(
      "cog://x.tif?v=2#color:CartoEarth,1,100"
    );
  });

  it("colorRamp → the plugin's #color: fragment, with the palette written out", () => {
    expect(colorRampFragment({ palette: "viridis", min: 0, max: 1, classes: 2 })).toBe(
      '#color:["#440154","#fde725"],0,1'
    );
    expect(colorRampFragment({ colors: ["#F00", "#00ff00"], min: -5, max: 35, reverse: true })).toBe(
      '#color:["#ff0000","#00ff00"],-5,35,c-'
    );
    // Smooth by default, with the palette's richest set of stops; default palette viridis.
    const smooth = colorRampFragment({ min: 0, max: 1 })!;
    expect(smooth).toMatch(/^#color:\["#440154",.*"#fde725"\],0,1,c$/);
    expect(colorRampColors({ palette: "ylgn", min: 0, max: 1 })!.length).toBe(9);
    // Can't be drawn: no fragment (validation has said why).
    expect(colorRampFragment({ palette: "viridiss", min: 0, max: 1 })).toBeUndefined();
    expect(colorRampFragment({ palette: "viridis", min: 1, max: 1 })).toBeUndefined();
    expect(colorRampFragment({ colors: ["red", "#fff"], min: 0, max: 1 })).toBeUndefined();
    // colorRamp replaces an authored fragment on a raster source.
    expect(cogUrl("x.tif#color:CartoEarth,1,100", { colorRamp: { colors: ["#000", "#fff"], min: 0, max: 1 } })).toBe(
      'cog://x.tif#color:["#000000","#ffffff"],0,1,c'
    );
  });

  it("cogSourceSpec: tileSize 256 unless set, mapbox encoding for elevation, no colorRamp key", () => {
    expect(cogSourceSpec({ type: "raster-dem", url: "e.tif", encoding: "terrarium" })).toEqual({
      type: "raster-dem",
      url: "cog://e.tif#dem",
      tileSize: 256,
      encoding: "mapbox",
    });
    expect(cogSourceSpec({ type: "raster", url: "e.tif", tileSize: 512, colorRamp: { min: 0, max: 1, classes: 2 } }))
      .toEqual({ type: "raster", url: 'cog://e.tif#color:["#440154","#fde725"],0,1', tileSize: 512 });
    expect(normalizeHex("#ABC")).toBe("#aabbcc");
    expect(normalizeHex("blue")).toBeUndefined();
  });
});

describe("the cog:// protocol core registers", () => {
  const host = (version = "6.12.0", registered: Record<string, unknown> = {}) => {
    const added: Record<string, (p: unknown, a: AbortController) => Promise<unknown>> = {};
    return {
      added,
      host: {
        addProtocol: ((name: string, fn: never) => {
          added[name] = fn;
          registered[name] = fn;
        }) as never,
        config: { REGISTERED_PROTOCOLS: registered },
        version,
        module: {},
      },
    };
  };

  it("registers once per module; a page's own registration wins", () => {
    const { host: h, added } = host();
    expect(install(h)).toBe("installed");
    expect(install(h)).toBe("already");
    expect(typeof added["cog"]).toBe("function");
    const own = host("6.12.0", { cog: () => undefined });
    expect(install(own.host)).toBe("host");
    expect(own.added["cog"]).toBeUndefined();
  });

  it("refuses maplibre-gl older than 4.5 (the plugin's floor) with a plain reason", () => {
    for (const version of ["3.6.2", "4.4.0"]) {
      let error: unknown;
      try {
        install(host(version).host);
      } catch (e) {
        error = e;
      }
      expect(isFormatError(error), version).toBe(true);
      expect((error as Error).message).toContain(`needs maplibre-gl 4.5 or later; this page runs ${version}`);
    }
    expect(install(host("4.5.0").host)).toBe("installed");
  });

  it("the library (plugin + header reader) loads on demand, through getDecoder('cog')", async () => {
    const lib = await getDecoder("cog");
    expect(typeof lib.cogProtocol).toBe("function");
    expect(typeof lib.readCogHeader).toBe("function");
    expect(await getDecoder("cog")).toBe(lib); // memoized
  });
});

describe("the reader's preflight: one 64 KB read, every failure in plain words", () => {
  let fetchSpy: ReturnType<typeof vi.spyOn>;
  const respond = (body: BodyInit | null, init: ResponseInit) => new Response(body, init);
  const partial = (name: string) =>
    respond(head(name), { status: 206, headers: { "content-range": `bytes 0-65535/${fixture(name).length}` } });

  beforeEach(() => {
    plugin.cogProtocol.mockClear();
    vi.spyOn(console, "warn").mockImplementation(() => {});
    fetchSpy = vi.spyOn(globalThis, "fetch");
  });
  afterEach(() => vi.restoreAllMocks());

  const failureOf = async (url: string) => {
    try {
      await handle({ url: `cog://${url}`, type: "json" });
    } catch (error) {
      return (error as { failure?: unknown }).failure;
    }
    return undefined;
  };

  it("a COG in Web Mercator: one range read, then the plugin", async () => {
    fetchSpy.mockResolvedValue(partial("imagery.cog.tif"));
    const out = await handle({ url: "cog://https://h.org/ok.tif#dem", type: "json" });
    expect(out).toEqual({ data: { tilejson: "2.2.0" } });
    expect(fetchSpy).toHaveBeenCalledTimes(1);
    expect((fetchSpy.mock.calls[0]![1] as RequestInit).headers).toEqual({ Range: "bytes=0-65535" });
    // Once per file: a second source (or map) on the same file reads nothing more.
    await handle({ url: "cog://https://h.org/ok.tif", type: "json" });
    expect(fetchSpy).toHaveBeenCalledTimes(1);
    expect(plugin.cogProtocol).toHaveBeenCalledTimes(2);
    // Tiles go straight to the plugin.
    await handle({ url: "cog://https://h.org/ok.tif#dem/10/545/373", type: "image" });
    expect(fetchSpy).toHaveBeenCalledTimes(1);
  });

  it("wrong projection → the gdalwarp command; the plugin never runs", async () => {
    fetchSpy.mockResolvedValue(partial("imagery-4326.cog.tif"));
    expect(await failureOf("https://h.org/latlon.tif")).toMatchObject({ code: "crs", crs: "EPSG:4326", format: "cog" });
    expect(plugin.cogProtocol).not.toHaveBeenCalled();
  });

  it("no range support, a 404, CORS, a web page", async () => {
    fetchSpy.mockResolvedValueOnce(respond(fixture("imagery.cog.tif"), { status: 200 }));
    expect(await failureOf("https://h.org/a.tif")).toMatchObject({ code: "no-range" });
    fetchSpy.mockResolvedValueOnce(respond("nope", { status: 404, statusText: "Not Found" }));
    expect(await failureOf("https://h.org/b.tif")).toMatchObject({ code: "http", status: 404 });
    fetchSpy.mockRejectedValueOnce(new TypeError("Failed to fetch"));
    expect(await failureOf("https://h.org/c.tif")).toMatchObject({ code: "cors" });
    fetchSpy.mockResolvedValueOnce(respond(fixture("not-really.tif"), { status: 206 }));
    expect(await failureOf("https://h.org/d.tif")).toMatchObject({ code: "not-format" });
    expect(plugin.cogProtocol).not.toHaveBeenCalled();
  });

  it("a failed preflight is not kept: the next request asks again", async () => {
    fetchSpy.mockRejectedValueOnce(new TypeError("Failed to fetch"));
    expect(await failureOf("https://h.org/retry.tif")).toMatchObject({ code: "cors" });
    fetchSpy.mockResolvedValueOnce(partial("imagery.cog.tif"));
    expect(await failureOf("https://h.org/retry.tif")).toBeUndefined();
  });

  it("not cloud-optimized: it still draws, with a console note and an author hint", async () => {
    fetchSpy.mockResolvedValue(partial("imagery-plain.tif"));
    const report = vi.fn();
    await handle({ url: "cog://https://h.org/plain.tif", type: "json" }, undefined, report);
    expect(plugin.cogProtocol).toHaveBeenCalledTimes(1);
    expect(report).toHaveBeenCalledWith("https://h.org/plain.tif", expect.stringContaining("gdal_translate -of COG"));
    expect(console.warn).toHaveBeenCalledWith(expect.stringContaining("is a GeoTIFF but not a Cloud Optimized one"));
  });

  it("the registered handler records the hint for the renderer (cogHintFor)", async () => {
    fetchSpy.mockResolvedValue(partial("imagery-plain.tif"));
    const added: Record<string, (p: unknown, a: AbortController) => Promise<unknown>> = {};
    install({
      addProtocol: ((name: string, fn: never) => (added[name] = fn)) as never,
      config: { REGISTERED_PROTOCOLS: {} },
      version: "6.12.0",
      module: {},
    });
    await added["cog"]!({ url: "cog://https://h.org/plain2.tif", type: "json" }, new AbortController());
    expect(cogHintFor("cog://https://h.org/plain2.tif#dem")).toContain("not a Cloud Optimized one");
  });
});

describe("classifyCogError — what the plugin and geotiff.js throw", () => {
  it.each([
    ["Server responded with full file", "no-range"],
    ["COG projection EPSG:2263 in x is not supported. Reproject to EPSG:3857 (Web Mercator).", "crs"],
    ["Failed to fetch", "cors"],
    ["Request failed", "cors"],
    ["Failed to construct 'Worker': Access to the script at 'blob:x' is denied by the document's Content Security Policy", "decoder"],
    ['"Bogus9" is not a supported color scheme', "read"],
  ])("%s → %s", (message, code) => {
    const error = classifyCogError(new Error(message), "/x.tif");
    expect((error as { failure?: { code?: string } }).failure?.code).toBe(code);
  });

  it("a codec file that couldn't be downloaded is the seam's 'chunk' failure, naming the file", () => {
    const error = classifyCogError(
      new TypeError("Failed to fetch dynamically imported module: https://cdn.example/dist/chunks/cog-jpeg.js"),
      "/x.tif"
    ) as { failure?: { code?: string; url?: string }; message: string };
    expect(error.failure).toMatchObject({ code: "chunk", url: "https://cdn.example/dist/chunks/cog-jpeg.js" });
    expect(error.message).toContain("couldn't be downloaded");
  });

  it("fileUrlOf drops the scheme, the fragment and the tile suffix", () => {
    expect(fileUrlOf("cog://https://h.org/a.tif#dem/3/4/5")).toBe("https://h.org/a.tif");
    expect(fileUrlOf("cog://https://h.org/a.tif/3/4/5")).toBe("https://h.org/a.tif");
    expect(fileUrlOf('cog://https://h.org/a.tif#color:["#000000","#ffffff"],0,1,c')).toBe("https://h.org/a.tif");
  });
});
